using PetstoreClient;
using PetstoreClient.Auth.OAuth;
using Xunit;

namespace Test;

public class OAuth2AuthCodeAuthenticatorTest
{
    private sealed class FakeApiClient : IApiClient
    {
        private readonly Queue<ApiResponse> _responses = new();

        public void Enqueue(string body, int statusCode = 200)
        {
            _responses.Enqueue(new ApiResponse(statusCode, body, new Dictionary<string, string>()));
        }

        public string? LastBody { get; private set; }
        public Uri? LastUrl { get; private set; }

        public Task<ApiResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body,
            bool noRedirect = false
        )
        {
            LastUrl = url;
            LastBody = body?.ToString();
            return Task.FromResult(_responses.Dequeue());
        }
    }

    private static readonly string[] Scopes = new[] { "read", "write" };

    private static OAuth2AuthorizationCodeAuthenticator CreateAuthenticator()
    {
        return new OAuth2AuthorizationCodeAuthenticator(
            "https://api.example.com",
            "my-client-id",
            "my-client-secret",
            new Uri("https://auth.example.com/authorize"),
            new Uri("https://auth.example.com/token"),
            null,
            new Uri("https://app.example.com/callback"),
            Scopes
        );
    }

    [Fact]
    public void BuildsAuthorizationUrlWithRequiredParams()
    {
        var auth = CreateAuthenticator();

        Uri url = auth.BuildAuthorizationUrl();

        string urlStr = url.ToString();
        Assert.Contains("response_type=code", urlStr);
        Assert.Contains("client_id=my-client-id", urlStr);
        Assert.Contains("redirect_uri=", urlStr);
        Assert.True(
            urlStr.Contains("scope=read%20write", StringComparison.Ordinal)
                || urlStr.Contains("scope=read+write", StringComparison.Ordinal)
                || urlStr.Contains("scope=read write", StringComparison.Ordinal)
        );
        Assert.StartsWith("https://auth.example.com/authorize?", urlStr);
    }

    [Fact]
    public void BuildsAuthorizationUrlWithState()
    {
        var auth = CreateAuthenticator();

        Uri url = auth.BuildAuthorizationUrl("csrf-state-123");

        Assert.Contains("state=csrf-state-123", url.ToString());
    }

    [Fact]
    public async Task ExchangesCodeWithCorrectGrantType()
    {
        var client = new FakeApiClient();
        client.Enqueue(
            "{\"access_token\":\"tok1\",\"refresh_token\":\"ref1\",\"expires_in\":3600}"
        );

        var auth = CreateAuthenticator();
        auth.SetApiClient(client);

        await auth.ExchangeCodeAsync("auth-code-xyz");

        Assert.NotNull(client.LastBody);
        Assert.Contains("grant_type=authorization_code", client.LastBody!);
        Assert.Contains("code=auth-code-xyz", client.LastBody!);
        Assert.Contains("client_id=my-client-id", client.LastBody!);
        Assert.Contains("client_secret=my-client-secret", client.LastBody!);
    }

    [Fact]
    public async Task IncludesRefreshTokenOnRefresh()
    {
        var client = new FakeApiClient();
        client.Enqueue("{\"access_token\":\"tok1\",\"refresh_token\":\"ref1\",\"expires_in\":1}");
        client.Enqueue("{\"access_token\":\"tok2\",\"expires_in\":3600}");

        var auth = CreateAuthenticator();
        auth.SetApiClient(client);

        await auth.ExchangeCodeAsync("auth-code-xyz");

        // GetAuthHeadersAsync triggers a refresh since token is expired
        Dictionary<string, string> headers = await auth.GetAuthHeadersAsync();

        Assert.Contains("refresh_token=ref1", client.LastBody!);
        Assert.Contains("grant_type=refresh_token", client.LastBody!);
        Assert.Equal("Bearer tok2", headers["Authorization"]);
    }

    [Fact]
    public async Task ThrowsBeforeExchangeCodeCalled()
    {
        var auth = CreateAuthenticator();

        await Assert.ThrowsAsync<InvalidOperationException>(() => auth.GetAuthHeadersAsync());
    }

    [Fact]
    public void GetHostReturnsConfiguredHost()
    {
        var auth = CreateAuthenticator();

        Assert.Equal("https://api.example.com", auth.GetHost());
    }

    [Fact]
    public async Task authHeadersBeforeExchangeReturnsRecoverableError()
    {
        var auth = CreateAuthenticator();

        // Calling GetAuthHeadersAsync before ExchangeCodeAsync is a
        // precondition violation. It must surface as a catchable exception
        // so callers can recover -- not as a process crash.
        InvalidOperationException caught = await Assert.ThrowsAsync<InvalidOperationException>(
            () => auth.GetAuthHeadersAsync()
        );
        Assert.NotNull(caught);

        // Caller continues normally after catching -- no process crash.
        Assert.Equal("https://api.example.com", auth.GetHost());
    }
